function createIcon(name: keyof typeof streamlineUiIconData): StreamlineIcon {
	const icon = streamlineUiIconData[name];
	return ({ size = 16, ...props }) => (
		<svg
			{...props}
			width={size}
			height={size}
			viewBox={`0 0 ${icon.width ?? 14} ${icon.height ?? 14}`}
			aria-hidden={props["aria-label"] ? undefined : true}
			focusable="false"
			dangerouslySetInnerHTML={{ __html: icon.body }}
		/>
	);
}

