export function getIconByName(name: string): StreamlineIcon | null {
	const direct = (streamlineUiIconData as Record<string, unknown>)[name]
		? (name as keyof typeof streamlineUiIconData)
		: undefined;
	const resolved = direct ?? TABLER_NAME_ALIASES[name];
	return resolved ? createIcon(resolved) : null;
}
